import os
import re
from pathlib import Path

import pytesseract
from openpyxl import Workbook
from PIL import Image, ImageFilter, ImageOps

IMG_DIR = Path("/app/workspace/dataset/img")
OUT_XLSX = Path("/app/workspace/stat_ocr.xlsx")

PRIORITY_KEYWORDS = [
    ("GRAND TOTAL",),
    ("TOTAL RM", "TOTAL: RM"),
    ("TOTAL AMOUNT",),
    (
        "NETT TOTAL",
        "NET TOTAL",
        "TOTAL DUE",
        "AMOUNT DUE",
        "BALANCE DUE",
        "TOTAL",
        "AMOUNT",
    ),
]

EXCLUSION_KEYWORDS = [
    "SUBTOTAL",
    "SUB TOTAL",
    "SUB-TOTAL",
    "TAX",
    "GST",
    "SST",
    "DISCOUNT",
    "CHANGE",
    "CASH TENDERED",
]

NUMBER_RE = re.compile(r"(?<![\w.])(\d{1,3}(?:,\d{3})*\.\d{2}|\d+\.\d{2})(?![\w.])")
DATE_PATTERNS = [
    re.compile(r"(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{4})"),
    re.compile(r"(\d{1,2})[/\-\.](\d{1,2})[/\-\.](\d{2})(?!\d)"),
]


def ocr_variants(img_path):
    """Yield OCR text produced by several preprocessing/PSM combinations."""
    img = Image.open(img_path)
    gray = ImageOps.grayscale(img)
    auto = ImageOps.autocontrast(gray, cutoff=5)
    w, h = auto.size
    big = auto.resize((w * 2, h * 2), Image.LANCZOS)
    sharp = big.filter(ImageFilter.SHARPEN)
    inv = ImageOps.invert(big)

    for variant, psm in [
        (big, "--psm 6"),
        (big, "--psm 4"),
        (auto, "--psm 6"),
        (sharp, "--psm 6"),
        (inv, "--psm 6"),
        (big, "--psm 11"),
    ]:
        try:
            yield pytesseract.image_to_string(variant, config=psm)
        except Exception:
            continue


def normalize_date(d, m, y):
    d, m, y = int(d), int(m), int(y)
    if y < 100:
        y += 2000 if y < 50 else 1900
    if m > 12 and d <= 12:
        d, m = m, d
    if not (1 <= m <= 12 and 1 <= d <= 31 and 1990 <= y <= 2099):
        return None
    return f"{y:04d}-{m:02d}-{d:02d}"


def extract_date(text):
    for pattern in DATE_PATTERNS:
        for match in pattern.finditer(text):
            iso = normalize_date(*match.groups())
            if iso:
                return iso
    return None


def line_has_exclusion(line_upper):
    for kw in EXCLUSION_KEYWORDS:
        if kw in line_upper:
            return True
    return False


def parse_amount(token):
    return token.replace(",", "")


def extract_total(text):
    lines = [ln.rstrip() for ln in text.splitlines()]
    for group in PRIORITY_KEYWORDS:
        candidate = None
        for idx, line in enumerate(lines):
            upper = line.upper()
            if line_has_exclusion(upper):
                continue
            if not any(kw in upper for kw in group):
                continue
            numbers = NUMBER_RE.findall(line)
            if numbers:
                candidate = parse_amount(numbers[-1])
                continue
            # Fallback: use last number on next non-empty line
            for next_line in lines[idx + 1 : idx + 3]:
                if not next_line.strip():
                    continue
                nxt_numbers = NUMBER_RE.findall(next_line)
                if nxt_numbers:
                    candidate = parse_amount(nxt_numbers[-1])
                break
        if candidate is not None:
            return candidate
    return None


def format_amount(amount):
    if amount is None:
        return None
    try:
        return f"{float(amount):.2f}"
    except ValueError:
        return None


def process(img_path):
    date = None
    total = None
    for text in ocr_variants(img_path):
        if date is None:
            date = extract_date(text)
        if total is None:
            total = extract_total(text)
        if date and total:
            break
    return date, format_amount(total)


def main():
    wb = Workbook()
    ws = wb.active
    ws.title = "results"
    ws.append(["filename", "date", "total_amount"])

    for img_path in sorted(IMG_DIR.iterdir()):
        if img_path.suffix.lower() not in {".jpg", ".jpeg", ".png"}:
            continue
        date, total = process(img_path)
        ws.append([img_path.name, date, total])
        print(f"{img_path.name}: date={date}, total={total}")

    wb.save(OUT_XLSX)


if __name__ == "__main__":
    main()
